function monthlyReport(now=today()){
 const ym=now.slice(0,7),count=new Date(Number(ym.slice(0,4)),Number(ym.slice(5)),0).getDate();
 const days=Array.from({length:count},(_,i)=>{const date=ym+'-'+String(i+1).padStart(2,'0'),entries=date<=now?(state.days[date]?.entries||[]):[];return {date,number:i+1,future:date>now,recorded:!!state.days[date]&&date<=now,entries,total:entries.length,completed:entries.filter(done).length,rate:entries.length?Math.round(entries.filter(done).length/entries.length*100):null}});
 const entries=days.flatMap(d=>d.entries),checks=entries.flatMap(e=>e.checkpoints),complete=entries.filter(done).length,missed=entries.filter(e=>!done(e)&&e.status==='missed').length;
 const categories=[...new Set([...state.categories.map(c=>c.id),...entries.map(e=>e.category)])].map(id=>{const list=entries.filter(e=>e.category===id);return {name:category(id)?.name||list[0]?.name||'Diğer',total:list.length,completed:list.filter(done).length,missed:list.filter(e=>!done(e)&&e.status==='missed').length,partial:list.filter(e=>!done(e)&&e.status!=='missed'&&e.checkpoints.some(p=>p.done)).length,checks:list.flatMap(e=>e.checkpoints).length,checksDone:list.flatMap(e=>e.checkpoints).filter(p=>p.done).length}});
 return {ym,days,entries,checks,complete,missed,categories,rate:entries.length?Math.round(complete/entries.length*100):0,checksDone:checks.filter(p=>p.done).length,recorded:days.filter(d=>d.recorded).length,active:days.filter(d=>d.completed>0).length};
}
function renderProgress(){
 const r=monthlyReport(),label=parse(r.ym+'-01').toLocaleDateString('tr-TR',{month:'long',year:'numeric'}),checkpointRate=r.checks.length?Math.round(r.checksDone/r.checks.length*100):0;
 const stat=(name,value,sub)=>`<div class="stat"><div><small>${name}</small><strong>${value}</strong><p class="note">${sub}</p></div></div>`;
 const w=720,h=200,pad=34,points=r.days.map((d,i)=>({x:pad+i*(w-pad*2)/(r.days.length-1),y:h-pad-(d.rate||0)*(h-pad*2)/100,d}));
 let path='',prev=false;for(const p of points){if(p.d.rate===null){prev=false;continue}path+=`${prev?'L':'M'}${p.x.toFixed(1)},${p.y.toFixed(1)} `;prev=true}
 const trend=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)} günlük kategori tamamlanma oranı">${[0,25,50,75,100].map(n=>{const y=h-pad-n*(h-pad*2)/100;return `<line class="chart-grid" x1="${pad}" x2="${w-pad}" y1="${y}" y2="${y}"/><text class="chart-label" x="${pad-7}" y="${y+4}" text-anchor="end">${n}%</text>`}).join('')}<path class="trend-line" d="${path}"/>${points.filter(p=>p.d.rate!==null).map(p=>`<circle class="trend-dot" cx="${p.x}" cy="${p.y}" r="4"><title>${p.d.number}: %${p.d.rate} · ${p.d.completed}/${p.d.total} kategori</title></circle>`).join('')}${points.filter((p,i)=>i===0||i===points.length-1||(i+1)%5===0).map(p=>`<text class="chart-label" x="${p.x}" y="${h-8}" text-anchor="middle">${p.d.number}</text>`).join('')}</svg>`;
 const colors=['var(--accent)','#d67575','#d5ae63','var(--chart-pending)'];
 $('#content').innerHTML=`<div class="section-head"><h2>${esc(label)}</h2><span class="note">Bugüne kadar · ${r.recorded} kayıtlı gün</span></div><div class="stats monthly-stats">${stat('Kategori tamamlama','%'+r.rate,`${r.complete} / ${r.entries.length} kategori`)}${stat('Checkpoint tamamlama','%'+checkpointRate,`${r.checksDone} / ${r.checks.length} checkpoint`)}${stat('Aktif gün',r.active,`${r.recorded} kayıtlı günün içinde`)}</div><p class="note">Yalnızca bu ayın bugün dahil geçmiş tarihlerindeki kayıtlı planlar hesaplanır. Açılmamış ve gelecek günler oranı düşürmez. Grafiklerde boşluk, kayıt olmadığını gösterir.</p><div class="progress-grid"><section class="panel trend-panel"><h2>Günlük tamamlanma</h2><p class="note">O gün tamamlanan kategorilerin tüm planlanan kategorilere oranı.</p><div class="trend-chart">${trend}</div>${!r.entries.length?'<p class="note">Bu ay henüz plan kaydı yok. İlk kayıtla grafik oluşacak.</p>':''}</section><section class="panel"><h2>Checkpoint dağılımı</h2><div class="donut-wrap"><svg class="donut" viewBox="0 0 120 120" role="img" aria-label="${r.checksDone} tamamlanan, ${r.checks.length-r.checksDone} bekleyen checkpoint"><circle class="donut-track" cx="60" cy="60" r="46"/><circle class="donut-value" cx="60" cy="60" r="46" pathLength="100" stroke-dasharray="${checkpointRate} 100" transform="rotate(-90 60 60)"/><text class="donut-number" x="60" y="59" text-anchor="middle">${r.checks.length?'%'+checkpointRate:'—'}</text><text class="chart-label" x="60" y="77" text-anchor="middle">tamamlandı</text></svg><div><p><i class="legend-dot completed"></i> ${r.checksDone} tamamlandı</p><p><i class="legend-dot pending"></i> ${r.checks.length-r.checksDone} bekliyor</p></div></div></section><section class="panel"><h2>Kategori performansı</h2><p class="note">Her çubuk, o kategoriye ait bu ayki günlük planların dağılımı.</p><div class="chart-legend"><span><i class="legend-dot completed"></i>Tamamlandı</span><span><i class="legend-dot missed"></i>Kaçırıldı</span><span><i class="legend-dot partial"></i>Kısmen</span><span><i class="legend-dot pending"></i>Bekliyor</span></div>${r.categories.map(c=>{const counts=[c.completed,c.missed,c.partial,c.total-c.completed-c.missed-c.partial];return `<div class="category-line"><div><span>${esc(c.name)}</span><span>${c.completed}/${c.total} · ${c.total?'%'+Math.round(c.completed/c.total*100):'—'}</span></div><div class="stacked-bar" role="img" aria-label="${esc(c.name)}: ${counts[0]} tamamlandı, ${counts[1]} kaçırıldı, ${counts[2]} kısmen, ${counts[3]} bekliyor">${counts.map((n,i)=>`<i style="width:${c.total?n/c.total*100:0}%;background:${colors[i]}"></i>`).join('')}</div><small class="note">Checkpoint: ${c.checksDone}/${c.checks}</small></div>`}).join('')}</section><section class="panel"><h2>Aylık aktivite haritası</h2><p class="note">Bir güne dokunarak günlük planına geçebilirsin.</p><div class="heatmap">${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'].map(n=>`<small>${n}</small>`).join('')}${'<span></span>'.repeat((parse(r.ym+'-01').getDay()+6)%7)}${r.days.map(d=>`<button class="heat-cell ${d.future?'future':''} ${d.rate===null?'no-data':'has-data'}" data-date="${d.date}" style="--intensity:${d.rate===null?0:Math.max(.08,d.rate/100)}" aria-label="${d.number}: ${d.future?'Gelecek gün':d.rate===null?'Kayıt yok':'%'+d.rate+' tamamlandı'}" title="${d.date}: ${d.rate===null?'Kayıt yok':'%'+d.rate}">${d.number}</button>`).join('')}</div><p class="note">Renk koyulaştıkça tamamlanma oranı artar. Çerçeveli soluk günler gelecekte.</p></section></div><details class="panel report-details"><summary>Günlük verileri tablo olarak göster</summary><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Gün</th><th>Kategori</th><th>Checkpoint</th><th>Tamamlanma</th></tr></thead><tbody>${r.days.filter(d=>!d.future).map(d=>{const cps=d.entries.flatMap(e=>e.checkpoints);return `<tr><td>${d.number}</td><td>${d.completed}/${d.total}</td><td>${cps.filter(p=>p.done).length}/${cps.length}</td><td>${d.rate===null?'Kayıt yok':'%'+d.rate}</td></tr>`}).join('')}</tbody></table></div></details>`;
}
